# Folk control: standard parametrization with ONE global learning rate scaled as 1/width (normalised to
# the base width), the heuristic practitioners reach for when a wide SP network diverges at the narrow
# network's LR -- for SGD (MLP) and for Adam (Transformer) alike.  NO-REFERENCE by design -- it is a
# control, not a published method; Yang & Hu 2022 (Sec. 3 / Figs. 1 and 3) motivate it by observing that
# under SP the optimal LR shifts down as width grows.
_CONTENT = '''class Parametrization:
    """Folk control: SP with a global learning rate proportional to base_width / width."""

    def __init__(self, width: int, base_width: int = 64, arch: str = "mlp", vocab_size: int = 0):
        self.width = int(width)
        self.base_width = int(base_width)
        self.arch = str(arch)
        self.vocab_size = int(vocab_size)

    def build(self) -> nn.Module:
        if self.arch == "transformer":
            return _Transformer(self.width, self.vocab_size, mu_readout=False)
        model = _MLP(self.width, mu_readout=False)
        for layer in model.hidden:
            nn.init.kaiming_normal_(layer.weight, a=1, mode="fan_in")
        nn.init.zeros_(model.readout.weight)
        return model

    def optimizer(self, model: nn.Module, lr: float):
        if self.arch == "transformer":
            return torch.optim.Adam(model.parameters(), lr=lr * self.base_width / self.width)
        return torch.optim.SGD(model.parameters(), lr=lr * self.base_width / self.width, momentum=0.9)
'''
