"""MLS-Bench score normalization system.

Provides unified [0,1] scoring across tasks with different metrics.
"""

from __future__ import annotations

import argparse
import sys
from pathlib import Path


def register_score_subcommand(subparsers: argparse._SubParsersAction) -> None:
    """Register the ``score`` subcommand with the main CLI parser."""
    p_score = subparsers.add_parser(
        "score",
        help="Compute normalized scores from leaderboard results",
    )

    p_score.add_argument(
        "task", nargs="?", default=None,
        help="Task name to score. Omit with --all to score everything.",
    )
    p_score.add_argument(
        "--all", action="store_true", dest="score_all",
        help="Score all tasks that have a score_spec.py",
    )
    p_score.add_argument(
        "--model", default=None,
        help="Only score a specific model (default: all models in leaderboard)",
    )
    p_score.add_argument(
        "--format", choices=["table", "json", "csv"], default="table",
        dest="out_format",
        help="Output format (default: table)",
    )
    p_score.add_argument(
        "--summary", action="store_true",
        help="Only show task-level scores (with --all)",
    )
    p_score.add_argument(
        "-v", "--verbose", action="store_true",
        help="Show per-term details",
    )
    p_score.add_argument(
        "--check", action="store_true",
        help="Validate score_spec files without scoring",
    )
    p_score.add_argument(
        "--anchors", action="store_true",
        help="Show baseline anchors for a task",
    )
    p_score.add_argument(
        "--autogen", action="store_true",
        help="Auto-generate score_spec.py templates from leaderboard data",
    )
    p_score.add_argument(
        "--force", action="store_true",
        help="Overwrite existing score_spec.py (with --autogen)",
    )
    p_score.add_argument(
        "--dry-run", action="store_true",
        help="Print generated spec without writing (with --autogen)",
    )

    p_score.set_defaults(func=cmd_score)


def cmd_score(args: argparse.Namespace) -> None:
    """Handler for the ``mlsbench score`` subcommand."""
    from mlsbench import PROJECT_ROOT
    tasks_dir = PROJECT_ROOT / "tasks"

    if args.autogen:
        _cmd_autogen(args, tasks_dir)
        return

    if args.anchors:
        _cmd_anchors(args, tasks_dir)
        return

    if args.check:
        _cmd_check(args, tasks_dir)
        return

    if args.score_all:
        _cmd_score_all(args, tasks_dir)
    elif args.task:
        _cmd_score_task(args, tasks_dir)
    else:
        print("Error: specify a task name or use --all", file=sys.stderr)
        sys.exit(1)


def _cmd_score_task(args: argparse.Namespace, tasks_dir: Path) -> None:
    from mlsbench.scoring.evaluate import evaluate_task
    from mlsbench.scoring.report import format_task_detail

    results = evaluate_task(args.task, model=args.model, tasks_dir=tasks_dir)
    if not results:
        print(f"No results for task '{args.task}'. Check score_spec.py and leaderboard.csv exist.")
        return

    if args.out_format == "json":
        from mlsbench.scoring.report import results_to_json
        print(results_to_json({args.task: results}))
    elif args.out_format == "csv":
        from mlsbench.scoring.report import results_to_csv
        print(results_to_csv({args.task: results}))
    else:
        print(format_task_detail(results, verbose=args.verbose))


def _cmd_score_all(args: argparse.Namespace, tasks_dir: Path) -> None:
    from mlsbench.scoring.evaluate import evaluate_all
    from mlsbench.scoring.report import format_summary_table, format_task_detail

    models = [args.model] if args.model else None
    all_results = evaluate_all(tasks_dir=tasks_dir, models=models)

    if not all_results:
        print("No scored tasks found. Ensure tasks have score_spec.py files.")
        return

    if args.out_format == "json":
        from mlsbench.scoring.report import results_to_json
        print(results_to_json(all_results))
    elif args.out_format == "csv":
        from mlsbench.scoring.report import results_to_csv
        print(results_to_csv(all_results))
    else:
        if args.summary:
            print(format_summary_table(all_results, summary_only=True))
        else:
            # Print summary table first
            print(format_summary_table(all_results))
            print()
            # Then per-task details if verbose
            if args.verbose:
                for task_name in sorted(all_results.keys()):
                    print(format_task_detail(all_results[task_name], verbose=True))
                    print()


def _cmd_check(args: argparse.Namespace, tasks_dir: Path) -> None:
    from mlsbench.scoring.anchors import BaselineAnchors
    from mlsbench.scoring.evaluate import load_expanded_spec
    from mlsbench.scoring.spec import leaderboard_declared_metrics, validate_score_spec

    targets: list[Path] = []
    if args.task:
        targets.append(tasks_dir / args.task)
    else:
        for d in sorted(tasks_dir.iterdir()):
            if d.is_dir() and (d / "score_spec.py").exists():
                targets.append(d)

    if not targets:
        print("No score_spec.py files found.")
        return

    total_warns = 0
    for task_dir in targets:
        task_name = task_dir.name
        anchors = BaselineAnchors(task_dir)
        spec = load_expanded_spec(task_dir, anchors)
        if spec is None:
            print(f"  {task_name}: no score_spec.py")
            continue

        if (task_dir / "leaderboard.csv").exists():
            available_metrics = sorted(set(anchors.metric_columns()) | set(leaderboard_declared_metrics(task_dir)))
        else:
            available_metrics = [ts.metric for ts in spec.terms.values()]
        warns = validate_score_spec(spec, available_metrics)
        if not (task_dir / "leaderboard.csv").exists():
            warns.append("leaderboard.csv not found; baseline anchors unavailable")
        else:
            missing_anchor_metrics: list[str] = []
            for tspec in spec.terms.values():
                if tspec.role == "drop":
                    continue
                if tspec.metric not in available_metrics:
                    continue
                if anchors.worst_for(tspec.metric, tspec.direction) is None:
                    missing_anchor_metrics.append(tspec.metric)
            if missing_anchor_metrics:
                metrics = sorted(set(missing_anchor_metrics))
                preview = ", ".join(metrics[:8])
                if len(metrics) > 8:
                    preview += f", ... (+{len(metrics) - 8} more)"
                warns.append(
                    f"{len(metrics)} metric(s) have no current baseline anchor: {preview}"
                )

        status = "OK" if not warns else f"{len(warns)} warning(s)"
        print(f"  {task_name}: {len(spec.terms)} terms, {len(spec.settings)} settings — {status}")
        for w in warns:
            print(f"    WARNING: {w}")
            total_warns += 1

    print(f"\nChecked {len(targets)} task(s), {total_warns} warning(s) total.")


def _cmd_anchors(args: argparse.Namespace, tasks_dir: Path) -> None:
    from mlsbench.scoring.anchors import BaselineAnchors
    from mlsbench.scoring.evaluate import load_expanded_spec

    if not args.task:
        print("Error: --anchors requires a task name", file=sys.stderr)
        sys.exit(1)

    task_dir = tasks_dir / args.task
    anchors = BaselineAnchors(task_dir)
    spec = load_expanded_spec(task_dir, anchors)
    directions: dict[str, str] = {}
    if spec:
        for term in spec.terms.values():
            previous = directions.get(term.metric)
            if previous is None:
                directions[term.metric] = term.direction
            elif previous != term.direction:
                directions[term.metric] = "mixed"

    bl_names = anchors.baseline_names()
    if not bl_names:
        print(f"No baselines found for task '{args.task}'.")
        return

    print(f"Task: {args.task}")
    print(f"Baselines: {', '.join(bl_names)}")
    print()

    if spec and spec.terms:
        cols = []
        seen = set()
        for term in spec.terms.values():
            if term.metric not in seen:
                cols.append(term.metric)
                seen.add(term.metric)
    else:
        cols = anchors.metric_columns()
    if not cols:
        print("No metric columns found.")
        return

    max_col = max(len(c) for c in cols)
    print(f"  {'Metric':<{max_col}}  {'Direction':>9}  {'Worst':>12}  {'Best':>12}")
    print(f"  {'-' * max_col}  {'-' * 9}  {'-' * 12}  {'-' * 12}")
    for c in cols:
        a = anchors.get(c)
        if a:
            direction = directions.get(c, "raw")
            if direction in {"higher", "lower"}:
                worst = anchors.worst_for(c, direction)
                best = anchors.best_for(c, direction)
            else:
                worst = a.worst
                best = a.best
            print(f"  {c:<{max_col}}  {direction:>9}  {worst:>12.4f}  {best:>12.4f}")
        else:
            direction = directions.get(c, "raw")
            print(f"  {c:<{max_col}}  {direction:>9}  {'missing':>12}  {'missing':>12}")


def _cmd_autogen(args: argparse.Namespace, tasks_dir: Path) -> None:
    from mlsbench.scoring.autogen import autogen_score_spec

    targets: list[str] = []
    if args.task:
        targets.append(args.task)
    else:
        # All tasks with leaderboard but no score_spec (unless --force)
        for d in sorted(tasks_dir.iterdir()):
            if not d.is_dir():
                continue
            if not (d / "leaderboard.csv").exists():
                continue
            if (d / "score_spec.py").exists() and not args.force:
                continue
            targets.append(d.name)

    if not targets:
        print("No tasks to generate score_spec for.")
        return

    generated = 0
    skipped = 0
    for task_name in targets:
        task_dir = tasks_dir / task_name
        if (task_dir / "score_spec.py").exists() and not args.force:
            skipped += 1
            continue

        source = autogen_score_spec(task_name, tasks_dir=tasks_dir, dry_run=args.dry_run)

        if args.dry_run:
            print(f"=== {task_name} ===")
            print(source)
            print()
        else:
            print(f"  {task_name}: generated")
        generated += 1

    action = "would generate" if args.dry_run else "generated"
    print(f"\n{action} {generated} score_spec(s), skipped {skipped} existing.")

"""Extract baseline anchors from leaderboard CSV.

Reads ``tasks/<task>/leaderboard.csv`` and identifies baseline rows
(``model=baseline:*``). Provides worst/best per-metric values for use
in normalization primitives.
"""

from __future__ import annotations

import json
from dataclasses import dataclass, field
from pathlib import Path

META_COLS = {"timestamp", "model", "is_final", "seed"}
INFORMATIONAL_PREFIXES = ("elapsed_", "n_samples", "n_prompts")


def _is_final(record: dict) -> bool:
    return str(record.get("is_final", "")).lower() == "true"


def _is_real_metric_value(value) -> bool:
    return isinstance(value, (int, float)) and not (
        isinstance(value, float) and value != value
    )


def _metric_count(record: dict) -> int:
    count = 0
    for key, value in record.items():
        if key in META_COLS:
            continue
        if str(key).startswith(INFORMATIONAL_PREFIXES) or str(key).endswith("_std"):
            continue
        if _is_real_metric_value(value):
            count += 1
    return count


def _baseline_row_priority(record: dict) -> tuple[int, bool, str, bool]:
    # Timestamp outranks is_final: a RE-MEASUREMENT supersedes an older run.
    # With is_final first, a stale single-seed row marked final beat a newer
    # 3-seed sweep that happened not to be flagged, so the sweep and the README
    # read the new data while score normalisation silently kept anchoring on
    # the old. is_final stays as the tie-break for two rows of the same age,
    # which is what it was really for.
    return (
        _metric_count(record),
        record.get("seed") == "mean",
        str(record.get("timestamp", "")),
        _is_final(record),
    )


@dataclass
class MetricAnchors:
    """Baseline anchor values for a single metric column."""
    worst: float
    best: float
    values: list[float] = field(default_factory=list)


class BaselineAnchors:
    """Read-only access to baseline anchor values from a task leaderboard."""

    def __init__(self, task_dir: Path):
        self._task_dir = Path(task_dir)
        self._anchors: dict[str, MetricAnchors] = {}
        self._baseline_names: list[str] = []
        self._metric_cols: list[str] = []
        self._load()

    # ------------------------------------------------------------------
    # Public API
    # ------------------------------------------------------------------

    def worst(self, metric: str) -> float | None:
        a = self._anchors.get(metric)
        return a.worst if a else None

    def best(self, metric: str) -> float | None:
        a = self._anchors.get(metric)
        return a.best if a else None

    def worst_for(self, metric: str, direction: str) -> float | None:
        """Return the raw baseline value that is worst for *direction*.

        ``worst()`` preserves the historical raw minimum API. Scoring code
        should use this helper so lower-is-better metrics floor at the raw
        maximum instead.
        """
        a = self._anchors.get(metric)
        if not a:
            return None
        if direction == "lower":
            return a.best
        return a.worst

    def best_for(self, metric: str, direction: str) -> float | None:
        """Return the raw baseline value that is best for *direction*."""
        a = self._anchors.get(metric)
        if not a:
            return None
        if direction == "lower":
            return a.worst
        return a.best

    def get(self, metric: str) -> MetricAnchors | None:
        return self._anchors.get(metric)

    def metric_columns(self) -> list[str]:
        """All scorable metric column names (excludes meta, elapsed_, *_std)."""
        return list(self._metric_cols)

    def baseline_names(self) -> list[str]:
        return list(self._baseline_names)

    # ------------------------------------------------------------------
    # Internal
    # ------------------------------------------------------------------

    def _load(self) -> None:
        from mlsbench.agent.leaderboard import Leaderboard

        lb_path = self._task_dir / "leaderboard.csv"
        if not lb_path.exists():
            return

        lb = Leaderboard(lb_path)
        records = lb.all_records()
        if not records:
            return

        cfg_path = self._task_dir / "config.json"
        bl_keys: set[str] = set()
        if cfg_path.exists():
            cfg = json.loads(cfg_path.read_text())
            bl_keys = set(cfg.get("baselines", {}).keys())

        # Identify current baseline rows. When config.json declares the current
        # baseline set, ignore stale baseline rows left over from older task
        # versions. Some valid historical anchors were not marked final, so
        # ``is_final`` is a preference signal rather than a hard filter.
        baseline_groups: dict[str, list[dict]] = {}
        for r in records:
            model = r.get("model")
            if not isinstance(model, str):
                continue
            if model.startswith("baseline:"):
                # str.removeprefix is Python 3.9+; slice instead so the scorer
                # runs under the task images' own 3.8 interpreter (the prefix is
                # guaranteed present by the startswith guard above).
                name = model[len("baseline:"):]
            elif model in bl_keys:
                name = model
            else:
                continue
            if bl_keys and name not in bl_keys:
                continue
            baseline_groups.setdefault(name, []).append(r)

        baseline_rows: list[tuple[str, dict]] = []
        for name, rows_for_baseline in baseline_groups.items():
            rows_with_metrics = [r for r in rows_for_baseline if _metric_count(r) > 0]
            if not rows_with_metrics:
                continue
            # A baseline's settings are not guaranteed to share one row: a run
            # that covers a subset of labels writes its own seed=mean row with
            # only those columns. Taking the single richest row therefore drops
            # every setting measured in a different run -- cv-dbm-sampler lost
            # its whole fid_edges2handbags anchor that way, so that setting
            # scored every submission against nothing.
            #
            # Merge instead, highest-priority row first, with lower-priority
            # rows only FILLING GAPS. That keeps the previous winner's values
            # authoritative where they exist (so a re-measurement still wins
            # over a stale row) and recovers the columns it simply lacked.
            ordered = sorted(rows_with_metrics, key=_baseline_row_priority, reverse=True)
            merged = dict(ordered[0])
            for row in ordered[1:]:
                for key, value in row.items():
                    if key in META_COLS:
                        continue
                    if _is_real_metric_value(merged.get(key)):
                        continue
                    if _is_real_metric_value(value):
                        merged[key] = value
            baseline_rows.append((name, merged))

        if not baseline_rows:
            return

        self._baseline_names = [f"baseline:{name}" for name, _ in sorted(baseline_rows)]

        data_rows = [r for _, r in baseline_rows]

        # Discover metric columns. ``metric_columns()`` intentionally excludes
        # elapsed_* so autogen does not score wall time by default, but explicit
        # score_specs may still reference elapsed_*; keep anchors for those.
        anchor_cols: list[str] = []
        seen: set[str] = set()
        for r in records:
            for k in r:
                if k in seen:
                    continue
                seen.add(k)
                if k in META_COLS:
                    continue
                if k.endswith("_std"):
                    continue
                if _is_real_metric_value(r[k]):
                    anchor_cols.append(k)

        # Compute per-metric anchors from baseline data rows
        for col in anchor_cols:
            vals: list[float] = []
            for r in data_rows:
                v = r.get(col)
                if _is_real_metric_value(v):
                    vals.append(float(v))
            if vals:
                self._anchors[col] = MetricAnchors(
                    worst=min(vals),
                    best=max(vals),
                    values=vals,
                )

        self._metric_cols = [
            col for col in anchor_cols
            if col in self._anchors and not col.startswith(INFORMATIONAL_PREFIXES)
        ]

"""Verifier-side C1 metrics, independent of the editable Python interpreter.

The candidate submits image predictions, NEVER labels, category membership or
AUROC/AP/F1. Counts/order below are the existing frozen category_paths protocol
for archive cf4313b13603bec67abb49ca959488f7eedce2a9f7795ec54446c649ac98cd3d.
No candidate module, pickle, or candidate-selected file is loaded here.

This closes self-reported metric forgery. It does not claim to solve the
separate, pre-existing disclosure of labels in MVTec filenames/test ordering.
"""
from __future__ import annotations

import json
import math
from pathlib import Path

import numpy as np

from .prediction_frame import read_prediction_frame


# (category, normal images, anomalous images), in frozen manifest order.
CATEGORIES = (
    ("bottle", 20, 63), ("cable", 58, 92), ("capsule", 23, 109),
    ("carpet", 28, 89), ("grid", 21, 57), ("hazelnut", 40, 70),
    ("leather", 32, 92), ("metal_nut", 22, 93), ("pill", 26, 141),
    ("screw", 41, 119), ("tile", 33, 84), ("toothbrush", 12, 30),
    ("transistor", 60, 40), ("wood", 19, 60), ("zipper", 32, 119),
)
TEXTURES = {"carpet", "grid", "leather", "tile", "wood"}
AXES = {"coreset", "distance-metric", "feature-layer", "score-aggregation",
        "threshold-calibration"}


def trusted_profile(parser_file: str) -> str:
    """Only a protected task/render-copy config may opt into reduced counts.

Never consult worker output, worker env, or an agent-writable result file to
select a smaller evaluation set. The default delivery contract is full.
"""
    config = json.loads(Path(parser_file).with_name("config.json").read_text())
    profile = config.get("anomalib_prediction_profile", "full")
    if profile not in ("full", "smoke"):
        raise ValueError("unknown protected anomalib_prediction_profile")
    return profile


def _scalar(value, name):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise ValueError(f"{name} must be a finite number")
    try:
        value = float(value)
    except OverflowError as exc:
        raise ValueError(f"{name} is out of range") from exc
    if not math.isfinite(value):
        raise ValueError(f"{name} must be finite")
    return value


def _ranking(score, truth):
    # Deliberately preserve the old stable tie ordering and trapezoid formula;
    # changing metric definitions would invalidate the existing anchors.
    positives, negatives = int(truth.sum()), int((~truth).sum())
    if not positives or not negatives:
        raise ValueError("ranking needs both classes")
    ranked = truth[np.argsort(-score, kind="mergesort")]
    tp, fp = np.cumsum(ranked), np.cumsum(~ranked)
    tpr = np.concatenate(([0.0], tp / positives, [1.0]))
    fpr = np.concatenate(([0.0], fp / negatives, [1.0]))
    precision = tp / np.arange(1, len(tp) + 1)
    integrate = getattr(np, "trapezoid", None) or np.trapz
    return {"image_auroc": float(integrate(tpr, fpr)),
            "image_ap": float(precision[ranked].sum() / positives)}


def _threshold_metrics(score, truth, threshold):
    prediction = score >= threshold
    tp = int((prediction & truth).sum())
    fp = int((prediction & ~truth).sum())
    fn = int((~prediction & truth).sum())
    tn = int((~prediction & ~truth).sum())
    precision, recall = tp / max(1, tp + fp), tp / max(1, tp + fn)
    return {"decision_f1": 2 * precision * recall / max(1e-12, precision + recall),
            "balanced_accuracy": 0.5 * (recall + tn / max(1, tn + fp)),
            "normal_fpr": fp / max(1, fp + tn), "anomaly_recall": recall}


def score_predictions(raw_output: str, *, axis: str, profile: str) -> dict:
    if axis not in AXES or profile not in ("full", "smoke"):
        raise ValueError("unknown trusted prediction contract")
    frame = read_prediction_frame(raw_output)
    expected = {"scores", "runtime_seconds"}
    if axis == "threshold-calibration":
        expected.add("threshold")
    if set(frame) != expected:
        raise ValueError("unexpected prediction fields (labels/metrics/profile are not accepted)")
    groups = frame["scores"]
    if not isinstance(groups, list) or len(groups) != len(CATEGORIES):
        raise ValueError("expected predictions for exactly 15 categories")
    scores, labels = [], []
    for group, (category, good, bad) in zip(groups, CATEGORIES):
        if profile == "smoke":
            good, bad = min(good, 4), min(bad, 4)
        if axis == "threshold-calibration":
            good -= max(1, good // 2)
            bad -= max(1, bad // 2)
        if not isinstance(group, list) or len(group) != good + bad:
            raise ValueError(f"wrong prediction count for {category}; expected {good + bad}")
        scores.append(np.asarray([_scalar(v, "image prediction") for v in group],
                                 dtype=np.float64))
        labels.append(np.asarray([False] * good + [True] * bad))

    texture = [i for i, (name, _, _) in enumerate(CATEGORIES) if name in TEXTURES]
    objects = [i for i, (name, _, _) in enumerate(CATEGORIES) if name not in TEXTURES]
    partitions = {"texture": texture, "object_a": objects[:5], "object_b": objects[5:]}
    if axis in ("coreset", "distance-metric", "feature-layer"):
        rows = [_ranking(s, y) for s, y in zip(scores, labels)]
        metrics = {key: float(np.mean([row[key] for row in rows])) for key in rows[0]}
        for name, indices in partitions.items():
            metrics.update({f"{name}_{key}": float(np.mean([rows[i][key] for i in indices]))
                            for key in rows[0]})
    else:
        threshold = _scalar(frame["threshold"], "threshold") if "threshold" in frame else None
        def evaluate(s, y):
            return _ranking(s, y) if threshold is None else _threshold_metrics(s, y, threshold)
        metrics = evaluate(np.concatenate(scores), np.concatenate(labels))
        for name, indices in partitions.items():
            row = evaluate(np.concatenate([scores[i] for i in indices]),
                           np.concatenate([labels[i] for i in indices]))
            metrics.update({f"{name}_{key}": value for key, value in row.items()})
    metrics = {key: float(f"{value:.8f}") for key, value in metrics.items()}
    # Legacy diagnostic only: NO C1 score_spec consumes this self-reported time.
    elapsed = _scalar(frame["runtime_seconds"], "runtime_seconds")
    if elapsed < 0:
        raise ValueError("runtime_seconds must be nonnegative")
    metrics["runtime_seconds"] = float(f"{elapsed:.6f}")
    return metrics

"""Recompute CV metrics in the protected parser, never in candidate Python.

The wire format contains predictions only. Targets, settings and formulae come
from the protected task/runner tree. This prevents self-reported metric forgery;
it is not a sandbox or a claim that the public datasets have secret labels.
"""
from __future__ import annotations

import base64
import binascii
import hashlib
import json
import math
from functools import lru_cache
from pathlib import Path

import numpy as np

from .prediction_frame import read_prediction_frame

TARGET_SHA256 = "829f9ab154fa32d346eaa47dc43c7d5a96f0f8fd1b805bcffd58b1bb91782e52"
GROUPS = ("congeneric_large", "congeneric_small", "distinctive")


@lru_cache(maxsize=1)
def frozen_targets():
    raw = (Path(__file__).parent / "assets/cv_prediction_targets_v1.json").read_bytes()
    if hashlib.sha256(raw).hexdigest() != TARGET_SHA256:
        raise ValueError("protected CV target metadata SHA256 mismatch")
    return json.loads(raw)


def _balanced_labels(labels, limit):
    if limit == len(labels):
        return labels
    classes = sorted(set(labels))[:min(len(set(labels)), max(2, limit // 4))]
    counts = {label: labels.count(label) for label in classes}
    result, depth = [], 0
    while len(result) < limit:
        added = False
        for label in classes:
            if depth < counts[label] and len(result) < limit:
                result.append(label)
                added = True
        if not added:
            raise ValueError("protected retrieval sample limit cannot be balanced")
        depth += 1
    return result


def protected_labels(family, parser_file):
    key = "pml" if family.startswith("pml_") else family
    if key not in ("crowd", "pointnext", "pml"):
        raise ValueError("unknown prediction family")
    labels = frozen_targets()[key]["targets"]
    config = json.loads(Path(parser_file).with_name("config.json").read_text())
    protocol = config.get("prediction_evaluation", {"profile": "formal"})
    if not isinstance(protocol, dict) or set(protocol) - {"profile", "sample_limit"}:
        raise ValueError("invalid protected prediction evaluation configuration")
    profile = protocol.get("profile", "formal")
    limit = protocol.get("sample_limit", len(labels))
    if type(limit) is not int or not 1 <= limit <= len(labels):
        raise ValueError("invalid protected evaluation sample limit")
    if profile not in ("formal", "smoke"):
        raise ValueError("unknown protected evaluation profile")
    if profile == "formal" and limit != len(labels):
        raise ValueError("formal scoring requires the full frozen evaluation set")
    selected = _balanced_labels(labels, limit) if key == "pml" else labels[:limit]
    return np.asarray(selected, dtype=np.int64), profile == "formal"


def _vector(value, size, *, integer=False):
    if not isinstance(value, list) or len(value) != size:
        raise ValueError(f"expected {size} predictions")
    if any(type(x) not in ((int,) if integer else (int, float)) for x in value):
        raise ValueError("predictions have an invalid scalar type")
    try:
        result = np.asarray(value, dtype=np.int64 if integer else np.float64)
    except (OverflowError, ValueError) as exc:
        raise ValueError("prediction outside numeric range") from exc
    if not np.isfinite(result).all():
        raise ValueError("non-finite prediction")
    return result


def _crowd(frame, gold, formal):
    if set(frame) - {"predictions", "diagnostics"}:
        raise ValueError("unknown crowd prediction field")
    errors = _vector(frame.get("predictions"), len(gold)) - gold
    metrics = {"count_mae": float(np.mean(np.abs(errors))),
               "count_rmse": float(np.sqrt(np.mean(np.square(errors)))),
               "evaluation_images": float(len(gold))}
    groups = np.where(gold < 232, 0, np.where(gold < 427, 1, 2))
    for index, name in enumerate(("sparse", "medium", "dense")):
        values = errors[groups == index]
        if formal and len(values) < 10:
            raise ValueError("incomplete formal crowd density group")
        if not len(values):
            continue
        metrics[name + "_mae"] = float(np.mean(np.abs(values)))
        metrics[name + "_rmse"] = float(np.sqrt(np.mean(np.square(values))))
    # These are untrusted diagnostics, not inputs to any of the crowd score specs.
    diagnostics = frame.get("diagnostics", {})
    if not isinstance(diagnostics, dict) or set(diagnostics) - {
        "train_updates", "train_objective", "runtime_seconds"
    }:
        raise ValueError("unknown crowd diagnostic")
    for name, value in diagnostics.items():
        if type(value) not in (int, float) or not math.isfinite(value):
            raise ValueError("invalid crowd diagnostic")
        metrics[name] = float(value)
    return metrics


def _pointnext(frame, gold, formal):
    if set(frame) != {"predictions"}:
        raise ValueError("unknown point classification prediction field")
    prediction = _vector(frame["predictions"], len(gold), integer=True)
    if np.any(prediction < 0) or np.any(prediction >= 15):
        raise ValueError("point class outside [0, 15)")
    confusion = np.bincount(gold * 15 + prediction, minlength=225).reshape(15, 15)
    correct, total = confusion.diagonal(), confusion.sum(axis=1)
    valid = total > 0
    metrics = {"oa": float(correct.sum() / total.sum()),
               "macc": float((correct[valid] / total[valid]).mean())}
    for index, name in enumerate(("class_a", "class_b", "class_c")):
        block = slice(index * 5, (index + 1) * 5)
        n, c = total[block], correct[block]
        if n.sum() == 0:
            if formal:
                raise ValueError("incomplete formal point classification group")
            continue
        mask = n > 0
        metrics[name + "_oa"] = float(c.sum() / n.sum())
        metrics[name + "_macc"] = float((c[mask] / n[mask]).mean())
    return metrics


def decode_rankings(encoded, gold):
    if not isinstance(encoded, str):
        raise ValueError("rankings must be a base64 string")
    counts = np.bincount(gold)[gold] - 1
    width = int(counts.max())
    if width < 1:
        raise ValueError("retrieval requires repeated classes")
    expected_bytes = len(gold) * width * 2
    if len(encoded) != 4 * ((expected_bytes + 2) // 3):
        raise ValueError("ranking payload length does not match protected evaluation set")
    try:
        raw = base64.b64decode(encoded, validate=True)
    except (ValueError, binascii.Error) as exc:
        raise ValueError("invalid ranking base64") from exc
    if len(raw) != expected_bytes:
        raise ValueError("truncated ranking payload")
    ranking = np.frombuffer(raw, dtype="<u2").reshape(len(gold), width).astype(np.int64)
    if (ranking >= len(gold)).any() or (ranking == np.arange(len(gold))[:, None]).any():
        raise ValueError("out-of-range or self retrieval neighbor")
    if (np.diff(np.sort(ranking, axis=1), axis=1) == 0).any():
        raise ValueError("duplicate retrieval neighbor")
    return ranking


def retrieval_metrics(ranking, gold, groups=None, *, formal=True):
    # Preserve the original evaluator's float32 reductions and class averaging.
    # Explicit CPU tensors: the private parser does not allocate a GPU.
    import torch

    labels = torch.tensor(gold, dtype=torch.long, device="cpu")
    ranks = torch.tensor(ranking, dtype=torch.long, device="cpu")
    counts = torch.bincount(labels)[labels] - 1
    width = ranks.shape[1]
    matches = labels[ranks].eq(labels[:, None])
    r1 = matches[:, :1].any(1).float()
    r2 = matches[:, :min(2, width)].any(1).float()
    r4 = matches[:, :min(4, width)].any(1).float()
    positions = torch.arange(1, width + 1, dtype=torch.float32, device="cpu")[None]
    precision = matches.cumsum(1) / positions
    ap = (precision * matches * (positions <= counts[:, None])).sum(1) / counts.clamp_min(1)

    def summarise(mask):
        y, a, b, c, d = labels[mask], r1[mask], r2[mask], r4[mask], ap[mask]
        class_means = torch.stack([a[y == label].mean() for label in torch.unique(y)])
        decile = max(1, math.ceil(len(class_means) * 0.10))
        return {"recall_at_1": float(a.mean()), "recall_at_2": float(b.mean()),
                "recall_at_4": float(c.mean()), "map_at_r": float(d.mean()),
                "worst_decile_recall_at_1": float(class_means.sort().values[:decile].mean())}

    metrics = summarise(torch.ones(len(labels), dtype=torch.bool, device="cpu"))
    if groups is not None:
        group_tensor = torch.tensor(groups, dtype=torch.long, device="cpu")
        for index, name in enumerate(GROUPS):
            mask = group_tensor == index
            if int(mask.sum()) < 2:
                if formal:
                    raise ValueError("incomplete formal retrieval taxonomy group")
                continue
            metrics.update({name + "_" + k: v for k, v in summarise(mask).items()})
    return metrics


def _pml(frame, gold, family, formal):
    if set(frame) != {"rankings"} or not isinstance(frame["rankings"], dict):
        raise ValueError("expected only retrieval rankings")
    expected = {"epochs10", "epochs20", "epochs40"} if family == "pml_budget" else {"final"}
    if set(frame["rankings"]) != expected:
        raise ValueError("missing or extra protected retrieval setting")
    groups = None
    if family == "pml_taxonomy":
        groups = np.asarray(frozen_targets()["pml"]["groups"], dtype=np.int64)[gold]
    metrics = {}
    for setting in sorted(expected):
        ranking = decode_rankings(frame["rankings"][setting], gold)
        rows = retrieval_metrics(ranking, gold, groups, formal=formal)
        if setting in ("final", "epochs40"):
            metrics.update(rows)
        if family == "pml_budget":
            metrics.update({setting + "_" + key: value for key, value in rows.items()})
    return metrics


def score_predictions(raw_output, *, family, parser_file):
    frame = read_prediction_frame(raw_output)
    gold, formal = protected_labels(family, parser_file)
    if family == "crowd":
        metrics = _crowd(frame, gold, formal)
    elif family == "pointnext":
        metrics = _pointnext(frame, gold, formal)
    elif family in ("pml_budget", "pml_taxonomy"):
        metrics = _pml(frame, gold, family, formal)
    else:
        raise ValueError("unknown prediction family")
    if not metrics or not all(math.isfinite(value) for value in metrics.values()):
        raise ValueError("non-finite or empty derived metrics")
    return {key: float(f"{value:.8f}") for key, value in metrics.items()}

"""Explicit evaluation conditions produced by one or more execution batches.

Score DSL groups are metric aggregations, not necessarily distinct conditions.
Likewise, one process can produce several conditions (e.g. checkpoints) without
retraining. This opt-in contract maps real conditions to their producing command
and score groups, and checks completeness BEFORE seed averaging. It does not
prove evaluator correctness or replace a Harbor execution test.

A task that declares no contract still gets the weaker default rule in
``check_command_seed_coverage``: one successful run per command and seed, or the
record is invalid -- see that function for the coverage rule it enforces.
"""
from __future__ import annotations

import json
import math
from pathlib import Path

from .spec import load_score_spec


CONDITION_AXES = frozenset({
    "dataset", "subset", "corruption", "resolution", "checkpoint", "nfe",
    "context_length", "guidance_scale", "sequence_length", "protocol",
})


def evaluation_contract(task_dir: Path, config: dict | None = None) -> dict | None:
    """Validate an explicit contract; None preserves legacy command semantics.

Every scoring group must be owned exactly once, including auxiliary cost
groups, which are checked but never counted as evaluation conditions.
"""
    config = config if config is not None else json.loads((task_dir / "config.json").read_text())
    if "evaluation_settings" not in config:
        return None
    declarations = config["evaluation_settings"]
    if not isinstance(declarations, list) or not declarations:
        raise ValueError("evaluation_settings must be a nonempty list")
    commands = [tc.get("label", tc.get("cmd")) for tc in config.get("test_cmds", [])]
    if not commands or any(not isinstance(c, str) or not c for c in commands) or len(set(commands)) != len(commands):
        raise ValueError("evaluation_settings requires unique command labels")
    spec = load_score_spec(task_dir)
    if spec is None or not spec.settings:
        raise ValueError("evaluation_settings requires score_spec settings")
    owned = set()

    def columns(groups):
        if not isinstance(groups, list) or not groups or any(not isinstance(g, str) for g in groups):
            raise ValueError("score_settings must be a nonempty list of names")
        cols = set()
        for group in groups:
            if group not in spec.settings or group in owned:
                raise ValueError("unknown or multiply-owned score setting: " + group)
            owned.add(group)
            setting = spec.settings[group]
            terms = [t for t, w in setting.terms if w > 0] + list(setting.constraints)
            cols.update(spec.terms[t].metric for t in terms if spec.terms[t].role != "drop")
        if not cols:
            raise ValueError("evaluation setting has no required scored metrics")
        return sorted(cols)

    names, conditions, metric_sets = set(), set(), set()
    settings = []
    for declaration in declarations:
        if not isinstance(declaration, dict):
            raise ValueError("each evaluation setting must be an object")
        name, command = declaration.get("name"), declaration.get("command")
        condition = declaration.get("condition")
        if not isinstance(name, str) or not name or name in names:
            raise ValueError("evaluation setting names must be nonempty and unique")
        if command not in commands:
            raise ValueError("unknown producing command for " + name)
        if not isinstance(condition, dict) or not condition or not set(condition) <= CONDITION_AXES:
            raise ValueError("condition must name real dataset/protocol axes: " + name)
        if any(isinstance(v, bool) or not isinstance(v, (str, int, float)) or
               (isinstance(v, str) and not v.strip()) or
               (isinstance(v, (int, float)) and not math.isfinite(v)) for v in condition.values()):
            raise ValueError("invalid condition value: " + name)
        signature = json.dumps(condition, sort_keys=True)
        if signature in conditions:
            raise ValueError("duplicate evaluation condition: " + name)
        cols = columns(declaration.get("score_settings"))
        if tuple(cols) in metric_sets:
            raise ValueError("identical metric sets cannot establish distinct conditions: " + name)
        names.add(name)
        conditions.add(signature)
        metric_sets.add(tuple(cols))
        settings.append(dict(declaration, metrics=cols))
    if {s["command"] for s in settings} != set(commands):
        raise ValueError("every command must declare its evaluation conditions")
    auxiliary = config.get("evaluation_auxiliary_scores", {})
    if not isinstance(auxiliary, dict) or not set(auxiliary) <= set(commands):
        raise ValueError("invalid evaluation_auxiliary_scores command mapping")
    auxiliary = {command: columns(groups) for command, groups in auxiliary.items()}
    if owned != set(spec.settings):
        raise ValueError("unmapped score settings: " + ", ".join(sorted(set(spec.settings) - owned)))
    return {"settings": settings, "auxiliary": auxiliary, "commands": commands}


def _rc_ok(record: dict) -> bool:
    """A successful exit, judged the way score_task's ``_completed_eval_record``
    judges it. ``rc == 0`` alone is looser than it looks: ``False == 0`` is True
    in Python, so a record carrying ``rc: false`` -- which is what a JSON writer
    produces for a missing status in some shapes -- reads as success. The type
    check is what makes "the supervisor recorded a clean exit" mean that."""
    return type(record.get("rc")) is int and record["rc"] == 0


def check_evaluation_records(contract: dict, seeds: list[int], records: list[dict]) -> dict:
    """Require exactly one successful, complete result per command and seed.

Input records are produced by the trusted parser, not by an editable candidate.
Missing/duplicate records, nonzero exit codes, and missing/nonfinite metrics are
explicit errors. Neither another seed nor another command can fill their holes.
"""
    errors, evidence = [], []
    if not seeds or len(set(seeds)) != len(seeds):
        errors.append("expected seeds must be nonempty and unique")
    expected = {(command, seed) for command in contract["commands"] for seed in seeds}
    indexed = {}
    for record in records:
        key = (record.get("label"), record.get("seed"))
        if key not in expected:
            errors.append("unexpected command/seed record: %r" % (key,))
        indexed.setdefault(key, []).append(record)

    def finite(value):
        if isinstance(value, bool):
            return False
        try:
            return value is not None and math.isfinite(float(value))
        except (ValueError, TypeError, OverflowError):
            return False

    for command in contract["commands"]:
        for seed in seeds:
            found = indexed.get((command, seed), [])
            if len(found) != 1:
                errors.append("%s seed %s: expected one result, got %s" % (command, seed, len(found)))
            record = found[0] if len(found) == 1 else {}
            rc_ok = len(found) == 1 and _rc_ok(record) and not record.get("error")
            if not rc_ok:
                errors.append("%s seed %s: %s" % (
                    command, seed,
                    record["error"] if (len(found) == 1 and record.get("error"))
                    else "missing or unsuccessful exit status"))
            metrics = record.get("metrics") or {}
            for setting in contract["settings"]:
                if setting["command"] != command:
                    continue
                missing = [col for col in setting["metrics"] if not finite(metrics.get(col))]
                if missing:
                    errors.append("%s seed %s: missing/nonfinite %s" % (setting["name"], seed, missing))
                evidence.append({"name": setting["name"], "command": command, "seed": seed,
                                 "condition": setting["condition"], "valid": rc_ok and not missing,
                                 "missing": missing,
                                 "metrics": {col: float(metrics[col]) for col in setting["metrics"] if col not in missing}})
            auxiliary_missing = [col for col in contract["auxiliary"].get(command, []) if not finite(metrics.get(col))]
            if auxiliary_missing:
                errors.append("%s seed %s: missing/nonfinite auxiliary metrics %s" % (command, seed, auxiliary_missing))
    return {"schema_version": 1, "valid": not errors, "settings": evidence, "errors": errors}


def check_command_seed_coverage(commands: list[str], seeds: list[int], records: list[dict]) -> dict:
    """Default completeness rule: every (command, seed) must have produced one
    successful run.  Applies to tasks that declare no ``evaluation_settings``.

The explicit contract above is opt-in; without it the default rule still
requires one successful run per (command, seed), so a submission whose runs
fail or are killed cannot score as if they had all succeeded by averaging only
the surviving runs.

The decision this encodes: **a failed run makes the record invalid.**  It is
neither retried nor dropped.  This is the weaker half of the explicit
contract -- exit status and duplication only, no per-setting metric
requirement -- because a task with no contract may legitimately have a command
that produces no scored metric of its own, and a metric genuinely absent from
every seed is already caught downstream by ``_validate_setting``'s
missing-objective rule.

**Harness-generated exit codes count as failures too, and that is deliberate.**
score_task.py writes rc 124 for a wave timeout, 125 for a test_cmd whose
``compute`` cannot be allocated on the reserved GPUs, 126/127 for an unsafe or
missing eval script, and the budget check's own rc for a budget violation.  All
of them zero the whole submission rather than averaging the seeds that did
finish.  Dropping them instead would reopen the exploit above from the other
end: a timeout is submission-reachable (a slow enough editable path runs the
wave out of time), so "the runs that survived" would again be a best-of.  A
task that trips 125 or 127 has a bundle defect rather than a bad submission,
but the honest reading of that run is still "not scored" -- which is what
reward 0.0 means -- and the cause is named in the errors below and in
``eval_summary.json``.
"""
    errors = []
    if not commands:
        errors.append("no evaluation commands declared")
    if not seeds or len(set(seeds)) != len(seeds):
        errors.append("expected seeds must be nonempty and unique")
    expected = {(command, seed) for command in commands for seed in seeds}
    indexed: dict = {}
    for record in records:
        key = (record.get("label"), record.get("seed"))
        if key not in expected:
            errors.append("unexpected command/seed record: %r" % (key,))
        indexed.setdefault(key, []).append(record)
    evidence = []
    for command in commands:
        for seed in seeds:
            found = indexed.get((command, seed), [])
            record = found[0] if len(found) == 1 else {}
            ok = len(found) == 1 and _rc_ok(record) and not record.get("error")
            if len(found) != 1:
                errors.append("%s seed %s: expected one result, got %s" % (command, seed, len(found)))
            elif not _rc_ok(record):
                errors.append("%s seed %s: unsuccessful exit status (rc=%r)"
                              % (command, seed, record.get("rc")))
            elif record.get("error"):
                # The run exited 0 but produced no usable record -- a parser
                # exception, a missing log. Saying "expected one result, got 0"
                # here (which is what dropping the record used to produce) sends
                # the reader looking for a scheduling bug instead of at the
                # parser that raised.
                errors.append("%s seed %s: %s" % (command, seed, record["error"]))
            evidence.append({"command": command, "seed": seed, "valid": ok,
                             "rc": record.get("rc") if len(found) == 1 else None,
                             **({"error": record["error"]} if record.get("error") else {})})
    return {"schema_version": 1, "valid": not errors, "runs": evidence, "errors": errors}

"""Single-final-line mitigation, NOT independent evaluation or a sandbox.

This blocks append/atexit overwrites. A worker that fabricates its only metric
line and exits successfully can still cheat.
"""
from __future__ import annotations

import re


def finalized_log(raw_output: str, *, max_metric_lines: int = 1) -> str:
    if type(max_metric_lines) is not int or max_metric_lines < 1:
        raise ValueError("max_metric_lines must be a positive integer")
    lines = raw_output.splitlines()
    finals = [line for line in lines if line.startswith("FINAL_TEST_METRICS:")]
    if len(finals) != 1:
        raise ValueError(f"expected one shell final metric line, found {len(finals)}")
    payload = finals[0][len("FINAL_TEST_METRICS:"):].strip()
    if not payload or payload.startswith("INVALID"):
        raise ValueError(payload or "empty shell final metric line")
    original = [line[len("TEST_METRICS:"):].strip() for line in lines
                if line.startswith("TEST_METRICS:")]
    if max_metric_lines == 1:
        if original != [payload]:
            raise ValueError("missing, duplicate or inconsistent original metric line")
    else:
        # Opt-in only for fixed evaluators that emit disjoint condition groups.
        # Never implement a last-match-wins merge, including for nan/inf tokens
        # which the original numeric parser may ignore.
        if not 1 <= len(original) <= max_metric_lines or any(not p for p in original):
            raise ValueError("missing or excessive original metric records")
        keys = []
        for record in original:
            names = re.findall(r"\b([A-Za-z_][A-Za-z0-9_]*)\s*=", record)
            if not names:
                raise ValueError("metric record contains no assignments")
            keys.extend(names)
        if len(keys) != len(set(keys)):
            raise ValueError("duplicate metric key; refusing overwrite")
        if " ".join(payload.split()) != " ".join(" ".join(original).split()):
            raise ValueError("inconsistent combined final metric record")
    # Preserve protocol checks (e.g. BUDGET_TRACE), never other metric lines.
    diagnostics = [line for line in lines if "TEST_METRICS:" not in line]
    return "\n".join(diagnostics + ["TEST_METRICS: " + payload]) + "\n"


def require_shell_final_metrics(parser_type, *, max_metric_lines: int = 1):
    from mlsbench.agent.parsers import ParseResult

    class FinalizedParser(parser_type):
        def parse(self, cmd_label, raw_output):
            try:
                sanitized = finalized_log(raw_output, max_metric_lines=max_metric_lines)
            except ValueError as exc:
                return ParseResult(feedback=f"Invalid finalized evaluation: {exc}", metrics={})
            return super().parse(cmd_label, sanitized)

    FinalizedParser.__name__ = parser_type.__name__
    FinalizedParser.__qualname__ = parser_type.__qualname__
    FinalizedParser.__module__ = parser_type.__module__
    return FinalizedParser

"""Data-only prediction transport, never a transport for self-reported scores.

Call this in the host/private parser, not in the editable interpreter.  A second
frame invalidates the submission: neither first-match nor last-match wins.
"""
from __future__ import annotations

import json


MARKER = "MLSB_PREDICTIONS_V1:"
MAX_FRAME_BYTES = 2 * 1024 * 1024


def _unique_object(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError(f"duplicate prediction field: {key}")
        result[key] = value
    return result


def _nonfinite(value):
    raise ValueError(f"non-finite JSON number: {value}")


def read_prediction_frame(raw_output: str) -> dict:
    frames = [line[len(MARKER):].strip() for line in raw_output.splitlines()
              if line.startswith(MARKER)]
    if len(frames) != 1:
        raise ValueError(f"expected exactly one prediction frame, found {len(frames)}")
    if len(frames[0].encode("utf-8")) > MAX_FRAME_BYTES:
        raise ValueError("prediction frame exceeds byte limit")
    try:
        value = json.loads(frames[0], object_pairs_hook=_unique_object,
                           parse_constant=_nonfinite)
    except (ValueError, RecursionError) as exc:
        raise ValueError(f"invalid prediction JSON: {exc}") from exc
    if not isinstance(value, dict):
        raise ValueError("prediction frame must be an object")
    return value

"""Output formatting for score results (terminal tables, JSON, CSV)."""

from __future__ import annotations

import csv
import io
import json
from typing import Any

from mlsbench.scoring.evaluate import SettingResult, TaskResult


# ---------------------------------------------------------------------------
# Terminal table formatting
# ---------------------------------------------------------------------------

def format_task_detail(results: list[TaskResult], verbose: bool = False) -> str:
    """Render detailed scoring results for a single task."""
    if not results:
        return "No results to display."

    parts: list[str] = []
    task_name = results[0].task

    for tr in results:
        lines: list[str] = []
        lines.append(f"Task: {task_name}")
        lines.append(f"Model: {tr.model}")
        lines.append("")

        if tr.settings:
            # Setting table
            max_sname = max(len(sr.name) for sr in tr.settings)
            max_sname = max(max_sname, len("Setting"))
            hdr = f"  {'Setting':<{max_sname}} | Score"
            sep = f"  {'-' * max_sname}-+------"
            lines.append(hdr)
            lines.append(sep)
            for sr in tr.settings:
                lines.append(f"  {sr.name:<{max_sname}} | {sr.score:.3f}")
            lines.append(sep)
            lines.append(f"  {'Task Score (gmean)':<{max_sname}} | {tr.score:.3f}")
        else:
            lines.append(f"  Task Score: {tr.score:.3f}")

        if verbose and tr.settings:
            lines.append("")
            lines.append("  Term Details:")
            for sr in tr.settings:
                for t in sr.terms:
                    p = t.params
                    if t.score == 0.0 and p.get("reason") == "missing_value":
                        detail = "(missing)"
                    elif "gamma" in p:
                        detail = f"(bounded_power, gamma={p['gamma']:.2f})"
                    elif "scale" in p:
                        detail = f"(sigmoid, scale={p['scale']:.1f})"
                    elif "target" in p:
                        detail = f"(penalty, target={p['target']})"
                    else:
                        detail = ""
                    raw_str = f"{t.raw:.4f}" if not (t.raw != t.raw) else "NaN"
                    lines.append(
                        f"    [{sr.name}] {t.metric}: raw={raw_str} -> score={t.score:.3f} {detail}"
                    )

        if tr.warnings:
            lines.append("")
            for w in tr.warnings:
                lines.append(f"  WARNING: {w}")

        parts.append("\n".join(lines))

    return "\n\n".join(parts)


def format_summary_table(
    all_results: dict[str, list[TaskResult]],
    summary_only: bool = False,
) -> str:
    """Render a cross-task summary table.

    Columns: Task | model1 | model2 | ...
    """
    if not all_results:
        return "No scored tasks found."

    # Collect all models
    model_set: set[str] = set()
    for task_results in all_results.values():
        for tr in task_results:
            model_set.add(tr.model)
    models = sorted(model_set)

    if not models:
        return "No agent results found."

    # Build score lookup: {(task, model): score}
    scores: dict[tuple[str, str], float | None] = {}
    for task_name, task_results in all_results.items():
        for tr in task_results:
            scores[(task_name, tr.model)] = tr.score

    tasks = sorted(all_results.keys())

    # Format model names (truncate for display)
    def _short_model(m: str) -> str:
        # Remove common prefixes
        for prefix in ("claude-", "deepseek-", "gpt-", "qwen-"):
            if m.startswith(prefix):
                return m
        return m[:20]

    model_headers = [_short_model(m) for m in models]
    col_width = max(13, max(len(h) for h in model_headers) + 2)
    task_width = max(30, max(len(t) for t in tasks) + 2)

    lines: list[str] = []

    # Header
    hdr = f"{'Task':<{task_width}}"
    for mh in model_headers:
        hdr += f" | {mh:>{col_width}}"
    lines.append(hdr)

    # Separator
    sep = "-" * task_width
    for _ in models:
        sep += "-+-" + "-" * col_width
    lines.append(sep)

    # Rows
    model_task_scores: dict[str, list[float]] = {m: [] for m in models}
    for task_name in tasks:
        row = f"{task_name:<{task_width}}"
        for m in models:
            s = scores.get((task_name, m))
            if s is not None:
                row += f" | {s:>{col_width}.3f}"
                model_task_scores[m].append(s)
            else:
                row += f" | {'—':>{col_width}}"
        lines.append(row)

    # Overall row (gmean across tasks)
    lines.append(sep)
    from mlsbench.scoring.evaluate import _gmean
    overall_row = f"{'Overall (gmean)':<{task_width}}"
    for m in models:
        ts = model_task_scores[m]
        if ts:
            overall = _gmean(ts)
            overall_row += f" | {overall:>{col_width}.3f}"
        else:
            overall_row += f" | {'—':>{col_width}}"
    lines.append(overall_row)

    return "\n".join(lines)


